const b=$input.first().json.body||$input.first().json;
if(!b.siteId||!b.message)throw new Error('siteId and message required');
return[{json:{siteId:b.siteId,conversationId:b.conversationId||null,userId:b.userId||'anon',message:b.message,requestId:'req_'+Date.now(),image:b.image||null}}];

const inp=$('Validate').item.json;
const site=Array.isArray($input.first().json)?$input.first().json[0]:$input.first().json;
if(!site)throw new Error('Site not found');
const match=(site.repo_url||'').match(/github\.com\/([^/]+)\/([^/]+)/);
const owner=match?match[1]:'';
const repo=match?match[2].replace(/\.git$/,''):'';
const msg=inp.message.toLowerCase();

// Smart file selection
const files=[];
if(msg.match(/color|theme|style|css|dark|light/))files.push('src/app/globals.css');
if(msg.match(/header|nav/))files.push('src/components/Header.tsx');
if(msg.match(/footer/))files.push('src/components/Footer.tsx');
if(msg.match(/page|home|hero/)||files.length===0)files.push('src/app/page.tsx');

return[{json:{...inp,site:{id:site.id,name:site.name,repo_url:site.repo_url,branch:site.default_branch||'main'},owner,repo,branch:site.default_branch||'main',filesToFetch:[...new Set(files)].slice(0,3),fileContents:{}}}];

const ctx=$('Build Context').item.json;
const fly=$input.first().json;
const files=ctx.filesToFetch||[];
if(files.length===0)return[{json:{...ctx,previewUrl:fly.previewUrl||''}}];
return files.map(f=>({json:{...ctx,previewUrl:fly.previewUrl||'',currentFile:f}}));

const items=$input.all();
const ctx=$('Prepare Fetch').first().json;
const fileContents={};
for(const item of items){
  const path=item.json.currentFile;
  const content=item.json.content;
  if(path&&content){
    try{fileContents[path]=Buffer.from(content,'base64').toString('utf8');}catch(e){fileContents[path]='// Error decoding';}
  }
}
console.log('Loaded files:', Object.keys(fileContents));
return[{json:{siteId:ctx.siteId,conversationId:ctx.conversationId,userId:ctx.userId,message:ctx.message,image:ctx.image,requestId:ctx.requestId,site:ctx.site,owner:ctx.owner,repo:ctx.repo,branch:ctx.branch,previewUrl:ctx.previewUrl,fileContents}}];

const query=$fromAI('path','Directory path','string')||'.';
const ctx=$('Merge Files')?.item?.json||{};
const {owner,repo,branch}=ctx;
if(!owner)return 'Error: no repo';
try{
  const r=await this.helpers.httpRequest({method:'GET',url:`https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=1`,headers:{'Authorization':'Bearer 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','Accept':'application/vnd.github+json'}});
  const path=query.replace(/^\/+/,'').replace(/\/+$/,'');
  let files=(r.tree||[]).filter(f=>f.type==='blob').map(f=>f.path);
  if(path&&path!=='.')files=files.filter(f=>f.startsWith(path+'/'));
  return files.slice(0,40).join('\n');
}catch(e){return 'Error: '+e.message;}

const query=$fromAI('path','File path','string')||'';
const ctx=$('Merge Files')?.item?.json||{};
let filePath=query.trim();
if(!filePath)return 'Error: path required';
filePath=filePath.replace(/^\/+/,'');
if(ctx.fileContents&&ctx.fileContents[filePath])return 'File already in context:\n'+ctx.fileContents[filePath];
const {owner,repo,branch}=ctx;
if(!owner)return 'Error: no repo context';
try{
  const r=await this.helpers.httpRequest({method:'GET',url:`https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(filePath)}?ref=${branch}`,headers:{'Authorization':'Bearer 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','Accept':'application/vnd.github+json'}});
  if(r.content)return Buffer.from(r.content,'base64').toString('utf8');
  return 'Error: No content in response';
}catch(e){return 'Error reading file: '+e.message;}

const query=$fromAI('data','JSON with filePath and content','string');
const ctx=$('Merge Files')?.item?.json||{};
const {owner,repo,branch,siteId}=ctx;
if(!owner)return 'Error: no repo';
let filePath,content;
try{const p=JSON.parse(query);filePath=p.filePath;content=p.content;}catch{return 'Error: Invalid JSON {filePath,content}';}
if(!filePath||!content)return 'Error: filePath and content required';
filePath=filePath.replace(/^\/+/,'');
try{
  if(siteId){try{await this.helpers.httpRequest({method:'POST',url:'https://preview-orchestrator.fly.dev/preview/write',headers:{'Content-Type':'application/json'},body:JSON.stringify({siteId,filePath,content}),timeout:5000});}catch{}}
  let sha=null;
  try{const e=await this.helpers.httpRequest({method:'GET',url:`https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${branch}`,headers:{'Authorization':'Bearer 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','Accept':'application/vnd.github+json'}});sha=e.sha;}catch{}
  const body={message:(sha?'Update ':'Create ')+filePath,content:Buffer.from(content).toString('base64'),branch};if(sha)body.sha=sha;
  await this.helpers.httpRequest({method:'PUT',url:`https://api.github.com/repos/${owner}/${repo}/contents/${filePath}`,headers:{'Authorization':'Bearer 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','Accept':'application/vnd.github+json','Content-Type':'application/json'},body:JSON.stringify(body)});
  return JSON.stringify({success:true,file:filePath,action:sha?'updated':'created'});
}catch(e){return 'Error: '+e.message;}

const query=$fromAI('data','JSON with filePath, search, replace, startLine, endLine','string');
const ctx=$('Merge Files')?.item?.json||{};
const {owner,repo,branch,siteId}=ctx;
if(!owner)return 'Error: no repo';
let filePath,search,replace,startLine,endLine;
try{const p=JSON.parse(query);filePath=p.filePath||p.file_path;search=p.search;replace=p.replace;startLine=p.startLine||p.first_replaced_line;endLine=p.endLine||p.last_replaced_line;}catch{return 'Error: Invalid JSON';}
if(!filePath||!search||replace===undefined)return 'Error: filePath, search, replace required';
filePath=filePath.replace(/^\/+/,'');
try{
  const r=await this.helpers.httpRequest({method:'GET',url:`https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${branch}`,headers:{'Authorization':'Bearer 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','Accept':'application/vnd.github+json'}});
  let content=Buffer.from(r.content,'base64').toString('utf8');
  if(!content.includes(search.split('...')[0].trim()))return 'Error: search text not found';
  content=content.replace(search.includes('...')?new RegExp(search.split('...')[0].trim()+'[\\s\\S]*?'+search.split('...').pop().trim()):search,replace);
  if(siteId){try{await this.helpers.httpRequest({method:'POST',url:'https://preview-orchestrator.fly.dev/preview/write',headers:{'Content-Type':'application/json'},body:JSON.stringify({siteId,filePath,content}),timeout:5000});}catch{}}
  await this.helpers.httpRequest({method:'PUT',url:`https://api.github.com/repos/${owner}/${repo}/contents/${filePath}`,headers:{'Authorization':'Bearer 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','Accept':'application/vnd.github+json','Content-Type':'application/json'},body:JSON.stringify({message:'Update '+filePath,content:Buffer.from(content).toString('base64'),sha:r.sha,branch})});
  return JSON.stringify({success:true,file:filePath,action:'updated',lines:`${startLine||'?'}-${endLine||'?'}`});
}catch(e){return 'Error: '+e.message;}

const query=$fromAI('path','File path','string')||'';
const ctx=$('Merge Files')?.item?.json||{};
const {owner,repo,branch}=ctx;
if(!owner)return 'Error: no repo';
const filePath=query.trim().replace(/^\/+/,'');
if(!filePath)return 'Error: path required';
try{
  const e=await this.helpers.httpRequest({method:'GET',url:`https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${branch}`,headers:{'Authorization':'Bearer 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','Accept':'application/vnd.github+json'}});
  await this.helpers.httpRequest({method:'DELETE',url:`https://api.github.com/repos/${owner}/${repo}/contents/${filePath}`,headers:{'Authorization':'Bearer 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','Accept':'application/vnd.github+json','Content-Type':'application/json'},body:JSON.stringify({message:'Delete '+filePath,sha:e.sha,branch})});
  return JSON.stringify({success:true,deleted:filePath});
}catch(e){return 'Error: '+e.message;}

const query=$fromAI('query','Search pattern','string')||'';
const ctx=$('Merge Files')?.item?.json||{};
const {owner,repo}=ctx;
if(!owner)return 'Error: no repo';
try{
  const r=await this.helpers.httpRequest({method:'GET',url:`https://api.github.com/search/code?q=${encodeURIComponent(query)}+repo:${owner}/${repo}`,headers:{'Authorization':'Bearer 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','Accept':'application/vnd.github+json'}});
  if(r.items?.length>0)return 'Found in:\n'+r.items.slice(0,15).map(i=>i.path).join('\n');
  return 'No results';
}catch(e){return 'Error: '+e.message;}

const query=$fromAI('pattern','Text pattern','string')||'';
const ctx=$('Merge Files')?.item?.json||{};
const {owner,repo}=ctx;
if(!owner)return 'Error: no repo';
try{
  const r=await this.helpers.httpRequest({method:'GET',url:`https://api.github.com/search/code?q=${encodeURIComponent(query)}+repo:${owner}/${repo}`,headers:{'Authorization':'Bearer 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','Accept':'application/vnd.github+json'}});
  return r.items?.length>0?r.items.slice(0,20).map(i=>i.path).join('\n'):'No matches';
}catch(e){return 'Error: '+e.message;}

const query=$fromAI('data','JSON with oldPath and newPath','string');
const ctx=$('Merge Files')?.item?.json||{};
const {owner,repo,branch}=ctx;
let oldPath,newPath;
try{const p=JSON.parse(query);oldPath=p.oldPath;newPath=p.newPath;}catch{return 'Error: Invalid JSON';}
if(!oldPath||!newPath)return 'Error: oldPath and newPath required';
try{
  const e=await this.helpers.httpRequest({method:'GET',url:`https://api.github.com/repos/${owner}/${repo}/contents/${oldPath}?ref=${branch}`,headers:{'Authorization':'Bearer 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','Accept':'application/vnd.github+json'}});
  await this.helpers.httpRequest({method:'PUT',url:`https://api.github.com/repos/${owner}/${repo}/contents/${newPath}`,headers:{'Authorization':'Bearer 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','Accept':'application/vnd.github+json','Content-Type':'application/json'},body:JSON.stringify({message:'Rename '+oldPath,content:e.content,branch})});
  await this.helpers.httpRequest({method:'DELETE',url:`https://api.github.com/repos/${owner}/${repo}/contents/${oldPath}`,headers:{'Authorization':'Bearer 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','Accept':'application/vnd.github+json','Content-Type':'application/json'},body:JSON.stringify({message:'Rename '+oldPath+' (delete)',sha:e.sha,branch})});
  return JSON.stringify({success:true,from:oldPath,to:newPath});
}catch(e){return 'Error: '+e.message;}

const url=$fromAI('url','URL to fetch','string')||'';
if(!url)return 'Error: URL required';
try{
  const r=await this.helpers.httpRequest({method:'GET',url:url.startsWith('http')?url:'https://'+url,headers:{'User-Agent':'AutoMate/1.0'}});
  let c=typeof r==='string'?r:JSON.stringify(r);
  c=c.replace(/<script[^>]*>[\s\S]*?<\/script>/gi,'').replace(/<style[^>]*>[\s\S]*?<\/style>/gi,'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
  return c.substring(0,6000);
}catch(e){return 'Error: '+e.message;}

const query=$fromAI('query','Search query','string')||'';
try{
  const r=await this.helpers.httpRequest({method:'GET',url:`https://api.duckduckgo.com/?q=${encodeURIComponent(query)}&format=json&no_html=1`});
  let out=[];
  if(r.AbstractText)out.push(r.AbstractText);
  if(r.RelatedTopics?.length)r.RelatedTopics.slice(0,3).forEach(t=>{if(t.Text)out.push(t.Text);});
  return out.length?out.join('\n\n'):'No results';
}catch(e){return 'Error: '+e.message;}

const pkg=$fromAI('package','Package name','string')||'';
const ctx=$('Merge Files')?.item?.json||{};
const siteId=ctx.site?.id||ctx.siteId;
if(!siteId)return 'Error: no site';
if(!pkg)return 'Error: package name required';
try{
  const r=await this.helpers.httpRequest({method:'POST',url:'https://preview-orchestrator.fly.dev/preview/install',headers:{'Content-Type':'application/json'},body:JSON.stringify({siteId,packages:[pkg]}),timeout:120000});
  return JSON.stringify({success:true,installed:r.installed||[pkg]});
}catch(e){return 'Error: '+e.message;}

const pkg=$fromAI('package','Package name','string')||'';
const ctx=$('Merge Files')?.item?.json||{};
const {owner,repo,branch}=ctx;
if(!owner)return 'Error: no repo';
if(!pkg)return 'Error: package name required';
try{
  const r=await this.helpers.httpRequest({method:'GET',url:`https://api.github.com/repos/${owner}/${repo}/contents/package.json?ref=${branch}`,headers:{'Authorization':'Bearer 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','Accept':'application/vnd.github+json'}});
  const pkgJson=JSON.parse(Buffer.from(r.content,'base64').toString('utf8'));
  if(pkgJson.dependencies)delete pkgJson.dependencies[pkg];
  if(pkgJson.devDependencies)delete pkgJson.devDependencies[pkg];
  const newContent=JSON.stringify(pkgJson,null,2);
  await this.helpers.httpRequest({method:'PUT',url:`https://api.github.com/repos/${owner}/${repo}/contents/package.json`,headers:{'Authorization':'Bearer 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','Accept':'application/vnd.github+json','Content-Type':'application/json'},body:JSON.stringify({message:'Remove '+pkg,content:Buffer.from(newContent).toString('base64'),sha:r.sha,branch})});
  return JSON.stringify({success:true,removed:pkg});
}catch(e){return 'Error: '+e.message;}

const ctx=$('Merge Files').item.json;
const raw=$('AI Agent').item.json;
let out=raw?.output||'';
const steps=raw?.intermediateSteps||[];
const files=[];
const thinking=[];
for(const s of steps){
  if(s.action?.log){const m=s.action.log.match(/"text":"([^"]{1,200})/);if(m)thinking.push(m[1]);}
  const obs=s.observation||'';
  try{const o=JSON.parse(obs);if(o.success&&o.file)files.push(o.file);}catch{}
}
return[{json:{...ctx,plan:{humanSummary:out,thinking,warnings:files.length===0&&steps.length>2?['No files modified']:[]},filesCreated:files,iterations:steps.length}}];
